// AUTO-GENERATED from "Rural Property Purchase Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms under which Seventh Sky will provide Rural Property Purchase Services to assist the Client in identifying, assessing, negotiating and coordinating the purchase of a suitable rural property.</p><p style=\"margin:6px 0;\">The Agreement establishes the rights and responsibilities of both Parties in relation to property search, inspections, negotiations, documentation coordination, settlement support and other agreed purchase services.</p><p style=\"margin:6px 0;\">The specific Services, pricing and engagement scope applicable to each transaction will be confirmed in the approved Quotation, Work Order or Property Purchase Schedule.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the rural property purchase is completed;</li><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">the Agreement is terminated in accordance with this Agreement; or</li><li style=\"margin:2px 0;\">both Parties otherwise agree in writing.</li></ul><p style=\"margin:6px 0;\">Where the Client engages Seventh Sky on an exclusive basis, the exclusive engagement period shall be specified in the approved Quotation or Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">Depending on the selected engagement, Seventh Sky may provide one or more of the following Services.</p><p style=\"margin:6px 0;\">Only the Services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer Consultation &amp; Planning</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Property Requirement Assessment</li><li style=\"margin:2px 0;\">☐ Budget Planning</li><li style=\"margin:2px 0;\">☐ Purchase Strategy</li><li style=\"margin:2px 0;\">☐ Rural Market Guidance</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Property Search</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Rural Property Identification</li><li style=\"margin:2px 0;\">☐ Property Shortlisting</li><li style=\"margin:2px 0;\">☐ On-Market &amp; Off-Market Property Search</li><li style=\"margin:2px 0;\">☐ Property Comparison</li><li style=\"margin:2px 0;\">☐ Buyer Recommendation Report</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Inspection &amp; Property Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Inspection Scheduling</li><li style=\"margin:2px 0;\">☐ Site Visit Coordination</li><li style=\"margin:2px 0;\">☐ Buyer &amp; Seller Communication</li><li style=\"margin:2px 0;\">☐ Inspection Feedback</li><li style=\"margin:2px 0;\">☐ Follow-up Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Negotiation &amp; Transaction Support</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Offer Preparation</li><li style=\"margin:2px 0;\">☐ Offer Submission</li><li style=\"margin:2px 0;\">☐ Negotiation Support</li><li style=\"margin:2px 0;\">☐ Purchase Agreement Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li><li style=\"margin:2px 0;\">☐ Registration Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Documentation &amp; Professional Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Ownership Verification Coordination</li><li style=\"margin:2px 0;\">☐ Khatian Review Coordination</li><li style=\"margin:2px 0;\">☐ Dag &amp; Mutation Coordination</li><li style=\"margin:2px 0;\">☐ Property Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Survey Coordination</li><li style=\"margin:2px 0;\">☐ Legal Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Support Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Agricultural Assessment Coordination</li><li style=\"margin:2px 0;\">☐ Environmental Assessment Coordination</li><li style=\"margin:2px 0;\">☐ Loan Assistance Coordination</li><li style=\"margin:2px 0;\">☐ Utility Connection Coordination</li><li style=\"margin:2px 0;\">☐ Other</li></ul><p style=\"margin:6px 0;\">Additional Services may be included by written agreement.</p>"],
  ["BUYER REQUIREMENTS", "<p style=\"margin:6px 0;\">The Client's purchasing requirements shall be recorded in Schedule B or the approved Property Purchase Schedule.</p><p style=\"margin:6px 0;\">The information may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Preferred Property Type;</li><li style=\"margin:2px 0;\">Preferred District, Upazila or Location;</li><li style=\"margin:2px 0;\">Intended Use (Agricultural, Residential, Commercial, Investment or Other);</li><li style=\"margin:2px 0;\">Budget Range;</li><li style=\"margin:2px 0;\">Preferred Land Size;</li><li style=\"margin:2px 0;\">Finance Method;</li><li style=\"margin:2px 0;\">Expected Purchase Timeframe;</li><li style=\"margin:2px 0;\">Special Requirements;</li><li style=\"margin:2px 0;\">Selected Services; and</li><li style=\"margin:2px 0;\">Other agreed purchasing criteria.</li></ul><p style=\"margin:6px 0;\">Where any inconsistency exists between this Agreement and the approved Work Order or Property Purchase Schedule, the approved Work Order or Property Purchase Schedule shall prevail for that transaction.</p>"],
  ["CLIENT RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Client agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate personal, financial and purchasing information;</li><li style=\"margin:2px 0;\">provide truthful information regarding financing capability and purchase readiness;</li><li style=\"margin:2px 0;\">provide all documents reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">cooperate with inspections, meetings and negotiations;</li><li style=\"margin:2px 0;\">promptly notify Seventh Sky of any changes to purchasing requirements or financial circumstances;</li><li style=\"margin:2px 0;\">pay all agreed fees and approved third-party expenses in accordance with this Agreement;</li><li style=\"margin:2px 0;\">obtain independent legal, taxation, valuation, surveying, environmental, engineering and financial advice where appropriate;</li><li style=\"margin:2px 0;\">independently assess whether a property is suitable before entering into a purchase contract; and</li><li style=\"margin:2px 0;\">act honestly and in good faith throughout the purchase process.</li></ul><p style=\"margin:6px 0;\">The Client acknowledges that they remain responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">making the final purchasing decision;</li><li style=\"margin:2px 0;\">obtaining finance approval where applicable;</li><li style=\"margin:2px 0;\">satisfying themselves regarding the property's suitability and condition;</li><li style=\"margin:2px 0;\">reviewing all legal documentation before purchase; and</li><li style=\"margin:2px 0;\">complying with all applicable laws relating to the property purchase.</li></ul>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide the agreed Services with reasonable care and skill;</li><li style=\"margin:2px 0;\">identify suitable rural properties based on the Client's requirements;</li><li style=\"margin:2px 0;\">coordinate inspections and property viewings;</li><li style=\"margin:2px 0;\">communicate with sellers and their representatives where authorised;</li><li style=\"margin:2px 0;\">assist with negotiations where requested;</li><li style=\"margin:2px 0;\">coordinate with lawyers, surveyors, valuers, financial institutions and other approved professionals where required;</li><li style=\"margin:2px 0;\">keep the Client reasonably informed of significant developments throughout the purchase process;</li><li style=\"margin:2px 0;\">provide progress updates during the engagement; and</li><li style=\"margin:2px 0;\">coordinate settlement activities where included within the agreed Services.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts as the Rural Property Purchase Coordinator and Service Provider and does not act as the seller, legal adviser, surveyor, valuer, engineer or financial adviser.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before commencing the Services, Seventh Sky may issue a Quotation or Work Order specifying:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services;</li><li style=\"margin:2px 0;\">engagement type (exclusive or non-exclusive);</li><li style=\"margin:2px 0;\">professional fees;</li><li style=\"margin:2px 0;\">success fee (if applicable);</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected project timeframe; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Additional Services requested after commencement may require a revised Quotation, Work Order or approved variation before work proceeds.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The fees payable under this Agreement shall be specified in the approved Quotation, Work Order or Property Purchase Schedule.</p><p style=\"margin:6px 0;\">Depending on the selected Services, fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">consultation fees;</li><li style=\"margin:2px 0;\">rural property search and shortlisting;</li><li style=\"margin:2px 0;\">market research and preliminary property assessment;</li><li style=\"margin:2px 0;\">inspection and site visit coordination;</li><li style=\"margin:2px 0;\">negotiation support;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">professional coordination fees;</li><li style=\"margin:2px 0;\">success fee (where applicable);</li><li style=\"margin:2px 0;\">approved third-party service fees; and</li><li style=\"margin:2px 0;\">any other agreed Services.</li></ul><p style=\"margin:6px 0;\">The Client agrees to pay all agreed fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, registration fees, stamp duty, taxes, legal fees, survey fees, valuation fees, financing costs and other approved third-party expenses remain the responsibility of the Client unless otherwise agreed in writing.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Rural Property Purchase Services</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Deposit upon acceptance of the Quotation or Work Order (where applicable).</li><li style=\"margin:2px 0;\">Progress payments for approved milestone Services (if applicable).</li><li style=\"margin:2px 0;\">Final payment upon completion of the agreed Services or settlement of the rural property purchase, whichever occurs first.</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Success Fee Engagement</p><p style=\"margin:6px 0;\">Where the Parties agree to a Success Fee arrangement, the agreed Success Fee shall become payable upon successful completion of the rural property purchase and settlement.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payments may result in suspension of the Services.</p>"],
  ["PROPERTY PURCHASE SERVICES", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to identify rural properties that meet the Client's stated requirements.</p><p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">suitable properties are subject to market availability;</li><li style=\"margin:2px 0;\">asking prices and market values may change without notice;</li><li style=\"margin:2px 0;\">sellers have the right to accept, reject or withdraw offers;</li><li style=\"margin:2px 0;\">successful purchase of a property cannot be guaranteed; and</li><li style=\"margin:2px 0;\">the final decision to purchase any property remains solely with the Client.</li></ul><p style=\"margin:6px 0;\">Where requested, Seventh Sky may coordinate:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">rural property searches;</li><li style=\"margin:2px 0;\">property inspections and site visits;</li><li style=\"margin:2px 0;\">seller communication;</li><li style=\"margin:2px 0;\">offer preparation;</li><li style=\"margin:2px 0;\">negotiations;</li><li style=\"margin:2px 0;\">documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination; and</li><li style=\"margin:2px 0;\">post-purchase support Services.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Project timeframes may be affected by:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property availability;</li><li style=\"margin:2px 0;\">market conditions;</li><li style=\"margin:2px 0;\">seller response times;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">valuation or survey requirements;</li><li style=\"margin:2px 0;\">government approvals and registration processes;</li><li style=\"margin:2px 0;\">weather conditions affecting rural inspections;</li><li style=\"margin:2px 0;\">public holidays; or</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Client reasonably informed and provide an updated estimated timeframe where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">A variation occurs where the Client requests work outside the approved scope of Services or where additional work becomes necessary.</p><p style=\"margin:6px 0;\">Examples include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional rural property searches;</li><li style=\"margin:2px 0;\">inspections outside the agreed scope;</li><li style=\"margin:2px 0;\">extended negotiations;</li><li style=\"margin:2px 0;\">additional valuation, survey or environmental coordination;</li><li style=\"margin:2px 0;\">legal documentation coordination;</li><li style=\"margin:2px 0;\">finance or loan assistance coordination;</li><li style=\"margin:2px 0;\">agricultural or environmental assessment coordination;</li><li style=\"margin:2px 0;\">relocation assistance; or</li><li style=\"margin:2px 0;\">any other additional Services requested by the Client.</li></ul><p style=\"margin:6px 0;\">Where a variation affects the agreed Service Fees or project timeframe, Seventh Sky will provide a revised Quotation, Work Order or variation for the Client's approval before proceeding.</p>"],
  ["PROPERTY PURCHASE COORDINATION & THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where required, Seventh Sky may coordinate independent third-party professionals to assist with the property purchase.</p><p style=\"margin:6px 0;\">These may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">lawyers;</li><li style=\"margin:2px 0;\">surveyors;</li><li style=\"margin:2px 0;\">valuers;</li><li style=\"margin:2px 0;\">engineers;</li><li style=\"margin:2px 0;\">environmental consultants;</li><li style=\"margin:2px 0;\">agricultural consultants;</li><li style=\"margin:2px 0;\">financial institutions;</li><li style=\"margin:2px 0;\">government authorities; and</li><li style=\"margin:2px 0;\">other specialist service providers.</li></ul><p style=\"margin:6px 0;\">The Client acknowledges that these providers are independent businesses responsible for their own advice and services.</p><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as the coordinator of these Services and is not responsible for the professional advice, reports or decisions of any independent third-party provider.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be deemed complete when Seventh Sky has substantially delivered the Services specified in the accepted Quotation, Work Order or Property Purchase Schedule.</p><p style=\"margin:6px 0;\">Depending on the agreed scope, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property search completed;</li><li style=\"margin:2px 0;\">suitable properties presented;</li><li style=\"margin:2px 0;\">inspections coordinated;</li><li style=\"margin:2px 0;\">negotiations completed;</li><li style=\"margin:2px 0;\">documentation coordinated;</li><li style=\"margin:2px 0;\">settlement support provided; or</li><li style=\"margin:2px 0;\">other agreed Services completed.</li></ul><p style=\"margin:6px 0;\">Where the Client requests additional Services after completion, those Services shall be treated as a separate engagement or approved variation under this Agreement.</p>"],
  ["CLIENT COMPLAINTS", "<p style=\"margin:6px 0;\">If the Client is dissatisfied with any aspect of the Services, the Client should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">communicate with the Client throughout the review process;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue where appropriate; and</li><li style=\"margin:2px 0;\">advise the Client of the outcome.</li></ul><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">Seventh Sky will perform the agreed Services with reasonable care, skill and professional diligence.</p><p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky acts as a Rural Property Purchase Service Provider and Coordinator and does not provide legal, financial, taxation, engineering, surveying, valuation or investment advice.</p><p style=\"margin:6px 0;\">The Client remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">obtaining independent professional advice where appropriate;</li><li style=\"margin:2px 0;\">carrying out their own due diligence;</li><li style=\"margin:2px 0;\">assessing the suitability of the property; and</li><li style=\"margin:2px 0;\">making the final decision to purchase.</li></ul><p style=\"margin:6px 0;\">Seventh Sky is not responsible for decisions made by the Client, Seller or any independent third-party service provider.</p>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">To the maximum extent permitted by law, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">changes in market conditions or property values;</li><li style=\"margin:2px 0;\">property availability;</li><li style=\"margin:2px 0;\">unsuccessful negotiations;</li><li style=\"margin:2px 0;\">financing approval or refusal;</li><li style=\"margin:2px 0;\">government decisions or registration delays;</li><li style=\"margin:2px 0;\">title defects or undisclosed property issues;</li><li style=\"margin:2px 0;\">advice provided by independent third-party professionals;</li><li style=\"margin:2px 0;\">delays caused by Sellers or government authorities; or</li><li style=\"margin:2px 0;\">any indirect, incidental or consequential loss.</li></ul><p style=\"margin:6px 0;\">Where liability cannot be excluded by law, Seventh Sky's total liability shall not exceed the total Service Fees paid by the Client for the Services giving rise to the claim.</p><p style=\"margin:6px 0;\">Nothing in this clause excludes liability that cannot legally be excluded under applicable law.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Both Parties agree to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Seventh Sky may collect, use and disclose information only for the purpose of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the agreed Services;</li><li style=\"margin:2px 0;\">coordinating with Sellers and approved third-party service providers;</li><li style=\"margin:2px 0;\">complying with legal obligations; and</li><li style=\"margin:2px 0;\">managing its business operations.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be responsible for delays or failure to perform its obligations where caused by events beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">floods;</li><li style=\"margin:2px 0;\">fire;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">utility failures;</li><li style=\"margin:2px 0;\">civil unrest; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["CLIENT ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Client acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have read and understood this Agreement;</li><li style=\"margin:2px 0;\">all information provided to Seventh Sky is true and accurate to the best of their knowledge;</li><li style=\"margin:2px 0;\">Seventh Sky provides Rural Property Purchase Services only and does not guarantee that a suitable property will be identified or successfully purchased;</li><li style=\"margin:2px 0;\">the final decision to purchase any property remains solely with the Client;</li><li style=\"margin:2px 0;\">independent legal, financial, taxation, surveying, valuation and other professional advice should be obtained before purchasing a property where appropriate;</li><li style=\"margin:2px 0;\">independent third-party professionals remain responsible for their own advice and services;</li><li style=\"margin:2px 0;\">all agreed Service Fees and approved third-party costs remain payable in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">they have had the opportunity to obtain independent legal advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension of Services</p><p style=\"margin:6px 0;\">Seventh Sky may suspend all or part of the Services where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">fails to pay any outstanding amount in accordance with this Agreement;</li><li style=\"margin:2px 0;\">provides false or misleading information;</li><li style=\"margin:2px 0;\">fails to provide information or instructions reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">requests Seventh Sky to undertake any unlawful activity; or</li><li style=\"margin:2px 0;\">commits a material breach of this Agreement.</li></ul><p style=\"margin:6px 0;\">Where practicable, Seventh Sky will notify the Client before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing written notice to the other Party.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Client:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">repeatedly fails to pay agreed Service Fees;</li><li style=\"margin:2px 0;\">engages in fraudulent or unlawful conduct;</li><li style=\"margin:2px 0;\">deliberately circumvents Seventh Sky in breach of this Agreement; or</li><li style=\"margin:2px 0;\">otherwise acts in a manner that makes continuation of the Services unreasonable.</li></ul><p style=\"margin:6px 0;\">Upon termination:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Service Fees for work completed remain payable;</li><li style=\"margin:2px 0;\">approved third-party costs remain payable;</li><li style=\"margin:2px 0;\">obligations intended to survive termination shall continue to apply; and</li><li style=\"margin:2px 0;\">termination does not affect any rights or obligations accrued before the termination date.</li></ul>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Client acknowledges that Seventh Sky invests considerable time, resources and expertise in identifying suitable rural properties, sourcing opportunities, communicating with sellers and coordinating the purchase process.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a property, seller or purchase opportunity, the Client agrees not to intentionally bypass Seventh Sky to avoid payment of the agreed Service Fees.</p><p style=\"margin:6px 0;\">This obligation applies during the term of this Agreement and for twelve (12) months following the introduction of the relevant property.</p><p style=\"margin:6px 0;\">This clause does not restrict the Client from purchasing properties that were not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order, Property Purchase Schedule and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment to this Agreement must be made in writing and accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision shall not constitute a waiver of that provision;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, registered post, courier or email.</li></ul>"],
  ["GOVERNING LAW", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to use reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">Where a dispute cannot be resolved through negotiation, either Party may refer the matter to the competent courts of Bangladesh.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal advice;</li><li style=\"margin:2px 0;\">agree to be bound by the terms of this Agreement; and</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, each of which shall be deemed an original.</p>"],
];
